final_template:
AWSTemplateFormatVersion: "2010-09-09"
Description: "Amazon Verified Permissions Policy Store for Bookstore application"
Parameters:
  AdminExcludedUser:
    Type: String
    Description: "Username of the administrator to be excluded from viewing books"
    Default: "CHANGE-ME-AdminExcludedUser"
    ConstraintDescription: "Must be a non-empty string; replace the default value with an actual username."
  SpecificUser:
    Type: String
    Description: "Username of the specific user permitted to view a specific book"
    Default: "CHANGE-ME-SpecificUser"
    ConstraintDescription: "Must be a non-empty string; replace the default value with an actual username."
  SpecificBook:
    Type: String
    Description: "Book name that the specific user is permitted to view"
    Default: "CHANGE-ME-SpecificBook"
    ConstraintDescription: "Must be a non-empty string; replace the default value with an actual book name."

Resources:
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long"
                      }
                    }
                  },
                  "memberOfTypes": ["Role"]
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owningUser": {
                        "type": "Entity",
                        "name": "User"
                      }
                    }
                  }
                }
              },
              "commonTypes": {
                "Context": {
                  "type": "Record",
                  "attributes": {
                    "region": {
                      "type": "String"
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": ["User", "Role"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Context"
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": ["User", "Role"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Context"
                    }
                  }
                }
              }
            }
          }

  PolicyAdminViewAnyBook:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: "permit(principal in Bookstore::Role::\"Admin\", action == Bookstore::Action::\"View\", resource);"

  PolicyForbidExcludedAdmin:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: !Sub "forbid(principal == Bookstore::User::\"${AdminExcludedUser}\", action == Bookstore::Action::\"View\", resource);"

  PolicyPublisherViewOwned:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: "permit(principal in Bookstore::Role::\"Publisher\", action == Bookstore::Action::\"View\", resource) when { resource.owningUser == principal };"

  PolicySpecificUserSpecificBook:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: !Sub "permit(principal == Bookstore::User::\"${SpecificUser}\", action == Bookstore::Action::\"View\", resource == Bookstore::Book::\"${SpecificBook}\");"

  PolicyCustomerViewPremium:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: "permit(principal in Bookstore::Role::\"Customer\", action == Bookstore::Action::\"ViewWithPremiumOffers\", resource) when { principal is Bookstore::User && principal.yearsAsMember >= 2 };"

  PolicyForbidCustomerViewPremium:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: "forbid(principal in Bookstore::Role::\"Customer\", action == Bookstore::Action::\"ViewWithPremiumOffers\", resource) when { principal is Bookstore::User && principal.yearsAsMember < 2 };"

  PolicyForbidNonUSRegion:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Statement: "forbid(principal, action in [Bookstore::Action::\"View\", Bookstore::Action::\"ViewWithPremiumOffers\"], resource) unless { context.region == \"us\" };"

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/policy-store-id
      Type: String
      Value: !Ref BookstorePolicyStore
      Description: "Policy Store ID for Bookstore application"

Outputs:
  PolicyStoreId:
    Description: "Policy Store ID"
    Value: !Ref BookstorePolicyStore
  PolicyStoreIdParameterName:
    Description: "SSM Parameter name for Policy Store ID"
    Value: !Ref PolicyStoreIdParameter

{
  "Description": "Cognito-based authentication layer for Lex chatbot web UI with IAM roles for Lex V1/V2 and optional live chat API invoke permission.",
  "Parameters": {
    "IdentityPoolName": {
      "Type": "String",
      "Default": "identity pool",
      "Description": "Name of the Cognito identity pool and associated resources"
    },
    "LexV1BotName": {
      "Type": "String",
      "Default": "OrderFlowers",
      "Description": "Name of the Lex V1 bot (used if LexV2BotId is empty)"
    },
    "LexV2BotId": {
      "Type": "String",
      "Default": "",
      "Description": "Lex V2 bot ID (if provided, Lex V2 actions are used)"
    },
    "LexV2BotAliasId": {
      "Type": "String",
      "Default": "",
      "Description": "Lex V2 bot alias ID (required when LexV2BotId is provided)"
    },
    "ForceCognitoLogin": {
      "Type": "String",
      "Default": "false",
      "AllowedValues": ["true", "false"],
      "Description": "When true, denies unauthenticated Lex and live chat API actions"
    },
    "ShouldEnableLiveChat": {
      "Type": "String",
      "Default": "false",
      "AllowedValues": ["true", "false"],
      "Description": "When true, adds execute-api:Invoke permission for the live chat API"
    },
    "LiveChatApiArn": {
      "Type": "String",
      "Default": "",
      "Description": "ARN of the API Gateway endpoint to allow invoke (required when ShouldEnableLiveChat is true)"
    }
  },
  "Conditions": {
    "IsLexV1": {
      "Fn::Equals": [{"Ref": "LexV2BotId"}, ""]
    },
    "IsLexV2": {
      "Fn::Not": [{"Condition": "IsLexV1"}]
    },
    "IsForceLogin": {
      "Fn::Equals": [{"Ref": "ForceCognitoLogin"}, "true"]
    },
    "EnableLiveChat": {
      "Fn::And": [
        {"Fn::Equals": [{"Ref": "ShouldEnableLiveChat"}, "true"]},
        {"Fn::Not": [{"Fn::Equals": [{"Ref": "LiveChatApiArn"}, ""]}]}
      ]
    }
  },
  "Resources": {
    "UserPool": {
      "Type": "AWS::Cognito::UserPool",
      "DeletionPolicy": "Retain",
      "UpdateReplacePolicy": "Retain",
      "Properties": {
        "UserPoolName": {"Ref": "IdentityPoolName"},
        "UsernameAttributes": ["email"],
        "AutoVerifiedAttributes": ["email"],
        "Schema": [
          {"Name": "given_name", "Required": true, "Mutable": true, "AttributeDataType": "String"},
          {"Name": "family_name", "Required": true, "Mutable": true, "AttributeDataType": "String"},
          {"Name": "email", "Required": true, "Mutable": true, "AttributeDataType": "String"},
          {"Name": "preferred_username", "Required": true, "Mutable": true, "AttributeDataType": "String"}
        ],
        "Policies": {
          "PasswordPolicy": {
            "MinimumLength": 8,
            "RequireLowercase": true,
            "RequireUppercase": true,
            "RequireNumbers": true,
            "RequireSymbols": true
          }
        },
        "AccountRecoverySetting": {
          "RecoveryMechanisms": [
            {"Name": "verified_email", "Priority": 1}
          ]
        }
      }
    },
    "UserPoolClient": {
      "Type": "AWS::Cognito::UserPoolClient",
      "Properties": {
        "ClientName": {"Fn::Sub": "${IdentityPoolName}-client"},
        "GenerateSecret": false,
        "UserPoolId": {"Ref": "UserPool"},
        "ExplicitAuthFlows": ["ALLOW_USER_SRP_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"],
        "PreventUserExistenceErrors": "ENABLED"
      }
    },
    "IdentityPool": {
      "Type": "AWS::Cognito::IdentityPool",
      "Properties": {
        "IdentityPoolName": {"Ref": "IdentityPoolName"},
        "AllowUnauthenticatedIdentities": true,
        "CognitoIdentityProviders": [
          {
            "ClientId": {"Ref": "UserPoolClient"},
            "ProviderName": {"Fn::GetAtt": ["UserPool", "ProviderName"]},
            "ServerSideTokenCheck": false
          }
        ]
      }
    },
    "AuthRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Principal": {"Federated": "cognito-identity.amazonaws.com"},
              "Action": "sts:AssumeRoleWithWebIdentity",
              "Condition": {
                "StringEquals": {
                  "cognito-identity.amazonaws.com:aud": {"Ref": "IdentityPool"}
                }
              }
            }
          ]
        },
        "Policies": [
          {
            "PolicyName": "AuthRolePolicy",
            "PolicyDocument": {
              "Version": "2012-10-17",
              "Statement": [
                {
                  "Fn::If": [
                    "IsLexV1",
                    {
                      "Effect": "Allow",
                      "Action": ["lex:PostText", "lex:PostContent"],
                      "Resource": {"Fn::Sub": "arn:aws:lex:${AWS::Region}:${AWS::AccountId}:bot:${LexV1BotName}:*"}
                    },
                    {"Ref": "AWS::NoValue"}
                  ]
                },
                {
                  "Fn::If": [
                    "IsLexV2",
                    {
                      "Effect": "Allow",
                      "Action": ["lex:RecognizeText", "lex:RecognizeUtterance"],
                      "Resource": {"Fn::Sub": "arn:aws:lex:${AWS::Region}:${AWS::AccountId}:bot-alias/${LexV2BotId}/${LexV2BotAliasId}"}
                    },
                    {"Ref": "AWS::NoValue"}
                  ]
                },
                {
                  "Effect": "Allow",
                  "Action": ["polly:SynthesizeSpeech"],
                  "Resource": "*"
                },
                {
                  "Fn::If": [
                    "EnableLiveChat",
                    {
                      "Effect": "Allow",
                      "Action": "execute-api:Invoke",
                      "Resource": {"Ref": "LiveChatApiArn"}
                    },
                    {"Ref": "AWS::NoValue"}
                  ]
                }
              ]
            }
          }
        ]
      }
    },
    "UnauthRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Principal": {"Federated": "cognito-identity.amazonaws.com"},
              "Action": "sts:AssumeRoleWithWebIdentity",
              "Condition": {
                "StringEquals": {
                  "cognito-identity.amazonaws.com:aud": {"Ref": "IdentityPool"}
                }
              }
            }
          ]
        },
        "Policies": [
          {
            "PolicyName": "UnauthRolePolicy",
            "PolicyDocument": {
              "Version": "2012-10-17",
              "Statement": [
                {
                  "Fn::If": [
                    "IsForceLogin",
                    {"Ref": "AWS::NoValue"},
                    {
                      "Fn::If": [
                        "IsLexV1",
                        {
                          "Effect": "Allow",
                          "Action": ["lex:PostText", "lex:PostContent"],
                          "Resource": {"Fn::Sub": "arn:aws:lex:${AWS::Region}:${AWS::AccountId}:bot:${LexV1BotName}:*"}
                        },
                        {
                          "Effect": "Allow",
                          "Action": ["lex:RecognizeText", "lex:RecognizeUtterance"],
                          "Resource": {"Fn::Sub": "arn:aws:lex:${AWS::Region}:${AWS::AccountId}:bot-alias/${LexV2BotId}/${LexV2BotAliasId}"}
                        }
                      ]
                    }
                  ]
                },
                {
                  "Fn::If": [
                    "EnableLiveChat",
                    {
                      "Fn::If": [
                        "IsForceLogin",
                        {"Ref": "AWS::NoValue"},
                        {
                          "Effect": "Allow",
                          "Action": "execute-api:Invoke",
                          "Resource": {"Ref": "LiveChatApiArn"}
                        }
                      ]
                    },
                    {"Ref": "AWS::NoValue"}
                  ]
                }
              ]
            }
          }
        ]
      }
    },
    "IdentityPoolRoleAttachment": {
      "Type": "AWS::Cognito::IdentityPoolRoleAttachment",
      "Properties": {
        "IdentityPoolId": {"Ref": "IdentityPool"},
        "Roles": {
          "authenticated": {"Fn::GetAtt": ["AuthRole", "Arn"]},
          "unauthenticated": {"Fn::GetAtt": ["UnauthRole", "Arn"]}
        }
      }
    }
  },
  "Outputs": {
    "IdentityPoolId": {
      "Value": {"Ref": "IdentityPool"}
    },
    "UserPoolId": {
      "Value": {"Ref": "UserPool"}
    },
    "UserPoolClientId": {
      "Value": {"Ref": "UserPoolClient"}
    }
  }
}
